import { constants } from 'node:fs';
import { lstat, mkdir, open, readdir, realpath, statfs, unlink } from 'node:fs/promises';
import type { FileHandle } from 'node:fs/promises';
import { randomUUID } from 'node:crypto';
import { join, resolve } from 'node:path';
import type { UploadConfiguration } from '../config/environment.js';
import { AssetActivity, isAssetControlName, MAX_ASSET_CONTROL_BYTES } from './asset-activity.js';

// Every data name is generated by the server, never a client filename or URL.
export const ASSET_ID = /^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/;

export class StorageFullError extends Error {}

export class AssetStorage {
  private readonly directory: string;
  private readonly activity: AssetActivity;

  constructor(private readonly limits: Readonly<UploadConfiguration>) {
    this.directory = resolve(limits.directory);
    this.activity = new AssetActivity(this.directory);
  }

  async initialize(): Promise<void> {
    await mkdir(this.directory, { recursive: true, mode: 0o700 });
    await this.checkDirectory();
    const release = await this.beginWrite();
    try {
      const probe = this.path(randomUUID());
      const handle = await open(probe, 'wx', 0o600);
      try { await handle.sync(); }
      finally { await handle.close(); await unlink(probe); }
    } finally { await release(); }
  }

  beginWrite(): Promise<() => Promise<void>> { return this.activity.beginWrite(); }
  beginMaintenance(): Promise<() => Promise<void>> { return this.activity.beginMaintenance(); }

  private path(id: string): string {
    if (!ASSET_ID.test(id)) throw new Error('Invalid internal asset ID.');
    return join(this.directory, id);
  }

  private async checkDirectory(): Promise<void> {
    const info = await lstat(this.directory);
    if (!info.isDirectory() || info.isSymbolicLink() || resolve(await realpath(this.directory)) !== this.directory) {
      throw new Error('Private storage must be a real directory.');
    }
  }

  // Called inside the short shared database reservation lock. Pending rows
  // reserve their full future size even if a timed-out writer is still running.
  async checkCapacity(bytes: number, reservations: ReadonlyArray<{ id: string; byteSize: number }> = []): Promise<void> {
    await this.checkDirectory();
    let used = 0;
    const sizes = new Map<string, number>();
    for (const entry of await readdir(this.directory, { withFileTypes: true })) {
      let info;
      try { info = await lstat(join(this.directory, entry.name)); }
      catch (error) {
        // Another admitted writer may finish its probe/marker during the scan.
        if ((error as NodeJS.ErrnoException).code === 'ENOENT') continue;
        throw error;
      }
      if (!info.isFile() || info.isSymbolicLink()) throw new Error('Unexpected private storage entry.');
      if (isAssetControlName(entry.name)) {
        if (info.size > MAX_ASSET_CONTROL_BYTES) throw new Error('Invalid asset activity entry.');
        continue;
      }
      used += info.size;
      sizes.set(entry.name, info.size);
      if (!Number.isSafeInteger(used)) throw new Error('Invalid storage accounting.');
    }
    let outstanding = 0;
    for (const reservation of reservations) {
      outstanding += Math.max(0, reservation.byteSize - (sizes.get(reservation.id) ?? 0));
    }
    used += outstanding;
    const disk = await statfs(this.directory, { bigint: true });
    if (used + bytes > this.limits.maxDiskBytes ||
        disk.bavail * disk.bsize < BigInt(bytes) + BigInt(outstanding) + BigInt(this.limits.minFreeBytes)) {
      throw new StorageFullError();
    }
  }

  async write(id: string, data: Buffer): Promise<void> {
    await this.checkCapacity(data.length);
    const handle = await open(this.path(id), 'wx', 0o600);
    // Leave a failed/partial write as a counted orphan. Never unlink a file
    // whose metadata transaction may have committed despite a lost response.
    try { await handle.writeFile(data); await handle.sync(); }
    finally { await handle.close(); }
    // POSIX requires syncing the directory entry too before durable DB metadata.
    // Windows does not expose directory fsync through this Node API.
    if (process.platform !== 'win32') {
      const directory = await open(this.directory, 'r');
      try { await directory.sync(); }
      finally { await directory.close(); }
    }
  }

  async read(id: string, byteSize: number): Promise<FileHandle> {
    await this.checkDirectory();
    const path = this.path(id);
    const before = await lstat(path);
    if (!before.isFile() || before.isSymbolicLink() || before.size !== byteSize) throw new Error('Invalid stored image.');
    const handle = await open(path, constants.O_RDONLY | (constants.O_NOFOLLOW ?? 0));
    try {
      const actual = await handle.stat();
      if (!actual.isFile() || actual.size !== byteSize || actual.ino !== before.ino || actual.dev !== before.dev) {
        throw new Error('Stored image changed.');
      }
      return handle;
    } catch (error) {
      await handle.close();
      throw error;
    }
  }

  async inventory(): Promise<Array<{ id: string; modifiedAt: Date; byteSize: number }>> {
    await this.checkDirectory();
    const result = [];
    for (const entry of await readdir(this.directory, { withFileTypes: true })) {
      if (!ASSET_ID.test(entry.name)) continue;
      const info = await lstat(this.path(entry.name));
      if (!info.isFile() || info.isSymbolicLink()) throw new Error('Unexpected private storage entry.');
      result.push({ id: entry.name, modifiedAt: info.mtime, byteSize: info.size });
    }
    return result.sort((a, b) => a.id.localeCompare(b.id));
  }

  // Maintenance already holds the exclusive gate. Never follow a link, traverse
  // a directory or recursively delete anything. Missing files make retries safe.
  async remove(id: string): Promise<void> {
    await this.checkDirectory();
    const path = this.path(id);
    let info;
    try { info = await lstat(path); }
    catch (error) { if ((error as NodeJS.ErrnoException).code === 'ENOENT') return; throw error; }
    if (!info.isFile() || info.isSymbolicLink()) throw new Error('Invalid stored image.');
    await unlink(path);
    if (process.platform !== 'win32') {
      const directory = await open(this.directory, 'r');
      try { await directory.sync(); } finally { await directory.close(); }
    }
  }
}
